import os, sys, json
sys.path.insert(0, os.path.dirname(__file__))
from po_utils import parse_pot, write_po_files, load_existing_translations, TEMPLATES_DIR, TARGET_LOCALES

def load_salvaged(domain):
    json_path = os.path.join(os.path.dirname(__file__), 'salvaged_translations.json')
    if not os.path.exists(json_path):
        return {}
    with open(json_path, 'r', encoding='utf-8') as f:
        all_salvaged = json.load(f)
    if domain not in all_salvaged:
        return {}
    result = {}
    for key_str, locale_map in all_salvaged[domain].items():
        parts = key_str.split('|||', 1)
        ctx = parts[0] if parts[0] else None
        msgid = parts[1]
        result[(ctx, msgid)] = locale_map
    return result

# _d: build locale dict from positional values in TARGET_LOCALES order
# order: bg cs da de el es_ES fi fr hi hr | hu id it ja ko lt nl no pl pt_BR | ro ru sv_SE th tr uk vi zh_CN zh_TW he_IL
def _d(*v):
    assert len(v) == 30, f"Expected 30, got {len(v)}"
    return dict(zip(TARGET_LOCALES, v))
def _e(s):
    return {l: s for l in TARGET_LOCALES}

